// @ts-nocheck

import ProductChart from "./LineChart";
import AverageChart from "./ParentCompanyGraph";
import { useState, useEffect, useCallback, useRef} from 'react';
import Stack from '@mui/material/Stack';

import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import RandomChart from "./RandomScatter";
export default function GraphGrid({ graphData, products }) {
    console.log(products)
    const [cpiData, setCpiData] = useState(null)
        useEffect(() => {
              fetch('toBeUsed/normalizedCPI.json')
                  .then(response => response.json())
                  .then(cpiData => setCpiData(cpiData))
                  .catch(error => console.error('Error fetching data:', error));
            }, []);
            
    if (!graphData) {
            return (null)
    }

    const ToReturn = () => {
         switch (graphData.class) {
            case 2:
                    return (
    <Box sx={{ paddingTop:'3vh', right:'5vw'}}>
               <Stack direction="row" justifyContent={"center"} spacing={2}>
               <Stack direction="column" justifyContent={"center"} spacing={2}>
      <Box sx={{ borderRadius: '8px', padding: '10px',  border: 2,  borderColor:'primary.contrastText'}}>

    <Typography variant="h5" gutterBottom color="#e5e8d6" sx={{paddingLeft:'10vw'}}>
                  {graphData.values.id + ' Average Percent Increase in Price Per Year'}
                </Typography>
                        <Box sx={{height: '45vh'}}>
                        <AverageChart  graphData = {graphData.values}/>
            </Box>  
                        </Box>  

              </Stack>
                           <Stack direction="column" justifyContent={"center"} spacing={2}>
      <Box sx={{ borderRadius: '8px', padding: '10px',  border: 2,  borderColor:'primary.contrastText'}}>

        <Typography variant="h5" gutterBottom color="#e5e8d6" sx={{paddingLeft:'1vw'}}>
          {graphData.values.id + ' Adjusted Value given Percentage Change and CPI'}
        </Typography> 
                                <Box sx={{height: '45vh', width: '30vw'}}>

                    <RandomChart  graphData = {graphData.values} cpi={cpiData}/>
                                </Box>  
            </Box>  

               </Stack>
               </Stack>

            </Box>

                    )
                    break;
                  case 1:
                    return (
                        <Box sx={{height: '50vh', paddingTop:'3vh'}}>
                                <Box sx={{ height: '45vh',borderRadius: '8px', padding: '10px',  border: 2,  borderColor:'primary.contrastText'}}>

                            <Typography variant="h5" gutterBottom color="#e5e8d6" sx={{paddingLeft:'10vw'}}>
                                    {'Price'}
                            </Typography>
                            <ProductChart  graphData = {graphData.values} cpiData ={cpiData}/>
                        </Box>
                                                </Box>

                    )
                    break;
                  default:
                    return(<div>hi</div>)
                }
    }
    return (
        <ToReturn/>

  );
}
