// @ts-nocheck
import * as React from 'react';
import { useRef } from 'react';
import { ListItemText, ListItem, ListItemIcon } from '@mui/material';
import List from '@mui/joy/List';
import Box from '@mui/material/Box';

import Divider from '@mui/material/Divider';
import { StyledList, StyledListItem } from '../MuiStyles';
import ListItemButton from '@mui/material/ListItemButton';
import InboxIcon from '@mui/icons-material/MoveToInbox';
import ExpandMore from '@mui/icons-material/ExpandMore';
import NestedList from '../ListItem';
import Collapse from '@mui/material/Collapse';
import NavigateNextIcon from '@mui/icons-material/NavigateNext';
import MailIcon from '@mui/icons-material/Mail';
import { useEffect, useState } from 'react';
import { color, padding } from '@mui/system';
import { createTheme, ThemeProvider } from '@mui/material/styles';
import { currTheme } from '../Theme';


export default function TypeList({ type, setGrid }) {
  const [open, setOpen] = React.useState(false);
  const [item, setItem] = React.useState(type)
  const handleClick = (vals) => {
    setOpen(!open);
  };

  const handleChangeGrid = (vals) => {
    let currVals = vals.Type + ' Chart'
    setGrid({class: 1, type: currVals, list: vals.Products})
  }
  return (
        <div>
          
            <StyledListItem key={item.Category}
              disablePadding onClick={() => handleClick()}>
              <ListItemButton sx={{paddingTop:'3px', paddingLeft: '12px',paddingBottom:'3px'}}>
                <ListItemIcon size='large' sx= {{color: 'secondary.light', flexGrow:'0'}}>
                          {open ? <ExpandMore  fontSize= {'medium'}/> : <NavigateNextIcon  fontSize= {'medium'}/>}
                </ListItemIcon>
                <ListItemText primary={item.Category} sx={{paddingRight:'20px'}}/>
              </ListItemButton>
            </StyledListItem>

            <Collapse in={open} timeout="auto" unmountOnExit>
            <StyledList>
            {item.List.map((smallerType, index) => (
              <Box sx={{paddingLeft:'20px'}}>
                                           
                <StyledListItem  key={item.Category}disablePadding>
<Divider orientation="vertical" flexItem  sx={{ borderLeftWidth: '1.5px' }}/>
              <ListItemButton sx={{paddingTop:'3px', paddingBottom:'3px'}} onClick={()=>handleChangeGrid(smallerType)}>
                <ListItemText primary={smallerType.Type} />
              </ListItemButton>
                          </StyledListItem>
                          </Box>
            ))}
            </StyledList>
            </Collapse>
            </div>
  );
}
