import * as React from 'react';
import { LineChart, barElementClasses } from '@mui/x-charts/LineChart';
import dayjs from "dayjs";
import { axisClasses } from '@mui/x-charts/ChartsAxis';
import { currTheme } from '../../Theme';
import { ThemeProvider } from '@emotion/react';
import {
  blueberryTwilightPalette,
  mangoFusionPalette,
  cheerfulFiestaPalette,
  strawberrySkyPalette,
  rainbowSurgePalette,
  bluePalette,
  greenPalette,
  purplePalette,
  redPalette,
  orangePalette,
  yellowPalette,
  cyanPalette,
  pinkPalette,
} from '@mui/x-charts/colorPalettes';
export default function ProductChart({graphData, cpiData}) {
  if (!graphData) {
    return (null)
  }
  function getAsDate (date) {

    const splits = date.split('-')
    return (new Date(splits[2], splits[1], splits[0]))
  }
  const newArr = graphData.Date.map((value, index) => (
    getAsDate(value)
  ))
  return (
        <ThemeProvider theme={currTheme}>
    
    <LineChart
colors={mangoFusionPalette}
    xAxis={[
      {
            label: "Date",
            data: newArr,
            scaleType: "time",
             valueFormatter: (date) => dayjs(date).format("MM YYYY"),
    },
    ]}
yAxis={[{ 
      label: "Index 1982-1984 = 100", 

    }   ]}
      series={[
        {
          data: graphData.Price, label: 'Adjusted Product Price'
        },
      ]}
    />
          </ThemeProvider>
    
  );
}


