import * as React from 'react';
import Box from '@mui/material/Box';
import Drawer from '@mui/material/Drawer';
import IconButton from '@mui/material/IconButton';
import { Typography } from '@mui/material';
import Toolbar from '@mui/material/Toolbar';
import { createTheme, ThemeProvider } from '@mui/material/styles';
import { currTheme } from '../Theme';
import MenuIcon from '@mui/icons-material/Menu';
import Button from '@mui/material/Button';

export default function TopDrawer() {
  const [open, setOpen] = React.useState(true);
  const toggleDrawer = (newOpen: boolean) => () => {
    setOpen(newOpen);
  };
  const DrawerList = (
    <ThemeProvider theme={currTheme}>
             <Box sx={{paddingLeft: '10vw', paddingTop: '50px', width: '80vw', height: "20vh"}}>
             <Typography variant="h4" gutterBottom color='primary.contrastText'>
               {'Are Groceries really that much more expensive Nowadays?'}
                      </Typography>
                <Box sx={{paddingTop: '30px', width: '80vw'}}>

              <Typography variant="h5" gutterBottom color='primary.contrastText'>
             {"Using the internet archive, I scraped thousands of website snapshots from a popular online retailer to gather as much historical pricing data as I could find. This website represents the culmination of tens of thousands of product prices from as early as 2015"}
           </Typography>
            <Typography variant="h5" gutterBottom color='primary.contrastText'>
             {"Click any of the tabs to view pricing data. Click any row on the chart to view more complex graphs and insights."}
           </Typography>
                           <Box sx={{paddingTop:'20px'}}>

                 <Button onClick={toggleDrawer(false)} variant="contained">Continue</Button>
                        </Box>

                        </Box>


             </Box>
    </ThemeProvider>     
  );
  return (
              <ThemeProvider theme={currTheme}>

    <div>

            <IconButton
             size={'large'}
            onClick={toggleDrawer(true)}
            sx={[
              {
                 float: 'right',
                color:'primary.contrastText',
              },
              open && { display: 'none' },
            ]}
          >
            <MenuIcon fontSize= {'large'}/>
          </IconButton>
      <Drawer open={open}  onClose={toggleDrawer(false)}
                  anchor={'top'}
>
        {DrawerList}
      </Drawer>
    </div>
        </ThemeProvider>     

  );
}